	if (!(ptr = strchr(line, ' '))) // Potential out-of-bounds access
		goto out_err;
	len = ptr - line;

	line = ptr + 1;
	if (!(ptr = strchr(line, '\n'))) // Potential out-of-bounds access
		goto out_err;
	len = ptr - line;
```

